require_once __DIR__.'/../../app/layout.php';require_role('company');$uid=(int)current_user()['id'];$st=db()->prepare('SELECT * FROM company_profiles WHERE user_id=?');$st->execute([$uid]);$c=$st->fetch()?:[];
$st=db()->prepare('SELECT COUNT(*) FROM jobs WHERE company_id=?');$st->execute([$uid]);$jobs=(int)$st->fetchColumn();$st=db()->prepare('SELECT COUNT(*) FROM applications a JOIN jobs j ON j.id=a.job_id WHERE j.company_id=?');$st->execute([$uid]);$apps=(int)$st->fetchColumn();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$st=db()->prepare('UPDATE company_profiles SET company_name=?,description=?,website=?,location=? WHERE user_id=?');$st->execute([trim($_POST['company_name']??''),trim($_POST['description']??''),trim($_POST['website']??''),trim($_POST['location']??''),$uid]);flash('success','Profil perusahaan diperbarui.');redirect('company/dashboard.php');}
$st=db()->prepare("SELECT a.*,j.title,u.name candidate,cp.headline FROM applications a JOIN jobs j ON j.id=a.job_id JOIN users u ON u.id=a.candidate_id LEFT JOIN candidate_profiles cp ON cp.user_id=u.id WHERE j.company_id=? ORDER BY a.created_at DESC LIMIT 6");$st->execute([$uid]);$recent=$st->fetchAll();page_header('Dashboard perusahaan');?>
<section class="dashboard-head"><div class="container"><span class="eyebrow">PUSAT REKRUTMEN INKLUSIF</span><h1>Selamat datang, <?=e($c['company_name']?:current_user()['name'])?></h1><p>Temukan talenta dan bangun proses rekrutmen yang lebih aksesibel.</p><a class="btn btn-primary" href="<?=e(url('company/jobs.php'))?>">+ Kelola lowongan</a></div></section><section class="section"><div class="container"><div class="metrics"><div><small>Lowongan dibuat</small><b><?=$jobs?></b><span>Semua lowongan perusahaan</span></div><div><small>Total lamaran</small><b><?=$apps?></b><span>Kandidat yang melamar</span></div><div><small>Profil perusahaan</small><b><?=$c['company_name']?'✓':'—'?></b><span>Informasi perekrut</span></div></div><div class="dashboard-grid"><div class="panel"><h2>Lamaran terbaru</h2><?php if(!$recent):?><div class="empty"><p>Lamaran kandidat akan muncul di sini.</p><a class="btn btn-primary" href="<?=e(url('company/jobs.php'))?>">Buat lowongan</a></div><?php else:?><div class="table-wrap"><table><tr><th>Kandidat</th><th>Posisi</th><th>Status</th></tr><?php foreach($recent as $a):?><tr><td><?=e($a['candidate'])?><small><?=e($a['headline']?:'Pencari kerja')?></small></td><td><?=e($a['title'])?></td><td><span class="badge <?=e(badge_class($a['status']))?>"><?=e($a['status'])?></span></td></tr><?php endforeach;?></table></div><a class="link" href="<?=e(url('company/applicants.php'))?>">Kelola semua kandidat →</a><?php endif;?></div><div class="panel"><h2>Profil perusahaan</h2><form method="post" class="form"><?=csrf_field()?><label>Nama perusahaan<input name="company_name" required value="<?=e($c['company_name']??current_user()['name'])?>"></label><label>Lokasi<input name="location" value="<?=e($c['location']??'')?>"></label><label>Website<input type="url" name="website" value="<?=e($c['website']??'')?>" placeholder="https://..."></label><label>Tentang perusahaan<textarea name="description" rows="4"><?=e($c['description']??'')?></textarea></label><button class="btn btn-primary">Simpan profil</button></form></div></div></div></section><?php page_footer();?>
